mapper.select:
select
  studyid, checkdate, jlrq, jcjg, zjjl, jlys, tsjy, ylbj, jcys, tydl, zljy, zjys, zjrq
from view_jlb

    
        and studyid = #{studyid}
    
    
        and checkdate = #{checkdate}
    
    
        and jlrq = #{jlrq}
    
    
        and jcjg = #{jcjg}
    
    
        and zjjl = #{zjjl}
    
    
        and jlys = #{jlys}
    
    
        and tsjy = #{tsjy}
    
    
        and ylbj = #{ylbj}
    
    
        and jcys = #{jcys}
    
    
        and tydl = #{tydl}
    
    
        and zljy = #{zljy}
    
    
        and zjys = #{zjys}
    
    
        and zjrq = #{zjrq}
    

limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from view_jlb

    
        and studyid = #{studyid}
    
    
        and checkdate = #{checkdate}
    
    
        and jlrq = #{jlrq}
    
    
        and jcjg = #{jcjg}
    
    
        and zjjl = #{zjjl}
    
    
        and jlys = #{jlys}
    
    
        and tsjy = #{tsjy}
    
    
        and ylbj = #{ylbj}
    
    
        and jcys = #{jcys}
    
    
        and tydl = #{tydl}
    
    
        and zljy = #{zljy}
    
    
        and zjys = #{zjys}
    
    
        and zjrq = #{zjrq}

select count(*)
from 体检结论

    
        and date_format(jlrq,'%Y-%m-%d') = #{params.recordingDate}

select
预约id studyid,终检日期 checkdate,结论日期 jlrq,检查结果 jcjg,终检结论 zjjl,结论医生 jlys,提示建议 tsjy,'' ylbj,'' jcys,'' tydl,'' zljy,终检医生 zjys,终检日期 zjrq
from 体检结论

    
        and date_format(结论日期,'%Y-%m-%d') = #{jlb.params.recordingDate}
    

order by 结论日期
limit #{pageable.offset}, #{pageable.pageSize}
